import {createPerformanceGovernor,estimateSceneMemory} from './performance-core.js';
import {initCampaign} from './campaign-ui.js';
import {createCrewExperience} from './crew-experience.js';
import {initPlanner} from './planner.js';
import {THREE,scene,camera,renderer,canvas,base,ship,ground,stations,stationPositions,astronaut,enemyMesh,colors,beacons,captureGroup,engineFlames,effects,material,mesh,ring,box,glow,setQuality} from './world.js';
import {ROLES,makeCrew,makeMission,tickCrew,reload,fire,ability,nextPhase,advanceProgress,clamp,normalizeMove} from './core.js';
const $=id=>document.getElementById(id);let mission=makeMission(),crew=makeCrew();
let experience=null;let planning=false,designInspect=false,configuredPlan=null,designHardware=null;let designModifiers={speed:1,energyRegen:1,captureRate:1,fuelReserve:100,scienceBonus:0,difficulty:'standard'};
const units=ROLES.map((r,i)=>{const u=astronaut(i);u.group.position.set(-4+i*1.5,.05,7.8);u.walk=0;u.aiCD=0;return u;});units[0].selection.visible=true;
let enemies=[],projectiles=[],particles=[],deployables=[],rings=[],spawnClock=0,toastClock=0,hudClock=0,totalTime=0,mouseInside=false,muted=true,audioCtx,orbit=0,zoom=1,screenShake=0,invulnerable=0,spawnSerial=0,interaction=null,interacting=false,lastAim=new THREE.Vector3(0,0,-1),pausedForModal=false;const keys=new Set(),pointer={x:innerWidth/2,y:innerHeight/2,left:false,right:false};
const raycaster=new THREE.Raycaster(),mouseNDC=new THREE.Vector2(),aimPlane=new THREE.Plane(new THREE.Vector3(0,1,0),-1),aimPoint=new THREE.Vector3(),tmp=new THREE.Vector3(),cameraTarget=new THREE.Vector3(),cameraPos=new THREE.Vector3();
let stats={shots:0,hits:0,abilities:0};let best=0;try{best=Number(localStorage.getItem('tminus-best')||0);}catch{}
const isFlying=()=>mission.phase==='space'||mission.phase==='return';
const playerPos=()=>isFlying()?ship.position:units[mission.active].group.position;
function toast(text){$('toast').textContent=text;$('toast').classList.add('visible');toastClock=3.4;}
function tone(freq=440,len=.08,type='sine',volume=.03){if(muted)return;try{audioCtx??=new AudioContext();if(audioCtx.state==='suspended')audioCtx.resume();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.setValueAtTime(freq,audioCtx.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(30,freq*.45),audioCtx.currentTime+len);g.gain.setValueAtTime(volume,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+len);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+len);}catch{}}
const objectiveLabels=[];stations.forEach((s,i)=>{const label=document.createElement('div');label.className='world-label';label.style.setProperty('--role',colors[i]);label.innerHTML=`<div class="label-tag"><i></i> ${ROLES[i].job.toUpperCase()}</div><small>${ROLES[i].name} STATION</small>`;$('world-labels').append(label);objectiveLabels.push(label);});
function renderCrew(){ $('crew').innerHTML=ROLES.map((r,i)=>`<button class="crew-card ${i===mission.active?'active':''}" style="--role:${r.color}" data-role="${i}" title="${r.name} · ${r.weapon} · Key ${i+1}"><span class="number">${i+1}</span><span class="role-icon">${r.icon}</span><b>${r.name}</b><small id="crew-state-${i}">${i===mission.active?'IN CONTROL':'READY'} · 100%</small><span class="crew-health"><i id="crew-health-${i}"></i></span></button>`).join('');$('crew').querySelectorAll('button').forEach(b=>b.onclick=()=>switchCrew(Number(b.dataset.role)));renderLoadout();}
function renderLoadout(){const r=ROLES[mission.active];$('weapon-type').textContent=r.name+' LOADOUT';$('weapon-name').textContent=r.weapon;$('mag-size').textContent=r.mag;const data=[['LMB','Fire','fire'],['RMB',r.id===1?'Repair / aim':'Precision aim','aim'],['MMB',r.alt,'alt'],['Q',r.skill,'q'],['R','Reload','r'],['F',r.ultimate,'f']];$('abilities').innerHTML=data.map(([key,label,action])=>`<button class="ability ${action==='f'?'ultimate':''}" data-action="${action}" title="${key}: ${label}"><div class="cd"></div><kbd>${key}</kbd><small>${label}</small></button>`).join('');$('abilities').querySelectorAll('button').forEach(b=>{b.onclick=()=>{const a=b.dataset.action;if(a==='fire')shoot();else if(a==='aim'){toast(mission.active===1?'Hold right mouse to repair nearby crew and the ship.':'Hold right mouse to aim precisely.');}else if(a==='r'){if(reload(crew[mission.active]))tone(180,.12);}else useAbility(a);};});}
function switchCrew(i){if(i===mission.active||mission.ended)return;mission.active=i;units.forEach((u,k)=>u.selection.visible=k===i&&!isFlying());pointer.left=false;pointer.right=false;renderCrew();tone(520,.06);toast(ROLES[i].name+' online · '+ROLES[i].skill+' [Q]');}
function renderObjectives(){let html='';if(mission.phase==='build'){html=ROLES.map((r,i)=>`<div class="objective ${stations[i].done?'done':''}" style="--role:${r.color}"><span class="objective-mark">${stations[i].done?'✓':r.icon}</span><div><b>${r.job}</b><small>${r.name[0]+r.name.slice(1).toLowerCase()} ${stations[i].done?'· Online':'· Hold E at station'}</small></div><span class="status">${stations[i].done?'ONLINE':'OFFLINE'}</span></div>`).join('');$('objective-count').textContent=mission.installed+' / 4';$('objective-label').textContent='PRE-FLIGHT CHECKLIST';$('launch').textContent=mission.installed===4?'LAUNCH EXPEDITION ↗':'LAUNCH EXPEDITION ↗';$('launch').disabled=mission.installed<4;$('mission-note').textContent=mission.installed===4?'All systems go. Your next frontier awaits.':'Switch crew to bring every system online.';}
else if(isFlying()){const done=mission.phase==='return';html=`<div class="objective done"><span class="objective-mark">✓</span><div><b>${done?'Relics secured':'Launch sequence'}</b><small>${done?'All three beacons extracted':'Kestrel flight systems online'}</small></div></div><div class="objective"><span class="objective-mark">⌖</span><div><b>Clear the flight path</b><small>Mouse aim · Fire at interceptors</small></div></div><div class="objective"><span class="objective-mark">↗</span><div><b>${done?'Reach the jump gate':'Reach Kepler IV'}</b><small id="distance-label">Warp corridor traversal</small></div></div>`;$('objective-label').textContent=done?'HOMEWARD VECTOR':'FLIGHT OBJECTIVES';$('objective-count').textContent='LIVE';$('launch').disabled=true;$('launch').textContent=done?'JUMP DRIVE CHARGING':'AUTOPILOT ENGAGED';$('mission-note').textContent='Move to dodge. Your crew skills remain available.';}
else{html=beacons.map((b,i)=>`<div class="objective ${b.done?'done':''}"><span class="objective-mark">${b.done?'✓':'◈'}</span><div><b>Relic beacon ${'ABC'[i]}</b><small>${b.done?'Secured':'Hold E inside the signal ring'}</small></div><span class="status">${b.done?'DONE':Math.round(b.progress*100)+'%'}</span></div>`).join('');$('objective-label').textContent='EXTRACTION OBJECTIVES';$('objective-count').textContent=mission.captured+' / 3';$('launch').disabled=mission.captured<3;$('launch').textContent='RETURN TO ORBIT ↗';$('mission-note').textContent=mission.captured===3?'Relics secured. Start the return flight.':'Defend your crew and secure all three beacons.';}$('objectives').innerHTML=html;}
function updatePhaseUI(){const p=mission.phase;const titles={build:['Before the<br><em>countdown.</em>','Four specialists. One way off this rock.'],space:['Into the<br><em>unknown.</em>','Keep your heading. Clear the frontier.'],surface:['Leave no<br><em>one behind.</em>','Secure the relics. Hold your ground.'],return:['The long<br><em>way home.</em>','One final jump. Bring the crew back.']};$('phase-title').innerHTML=titles[p][0];$('phase-subtitle').textContent=titles[p][1];$('phase-status').textContent={build:'GROUNDED',space:'IN TRANSIT',surface:'EXTRACTING',return:'JUMP VECTOR'}[p];$('clock-label').textContent={build:'LAUNCH WINDOW',space:'ARRIVAL IN',surface:'EXTRACTION WINDOW',return:'JUMP GATE IN'}[p];$('location').innerHTML=p==='build'?'OUTPOST 07 <i>·</i> LUNAR FRONTIER':p==='surface'?'KEPLER IV <i>·</i> RELIC FIELDS':'DEEP SPACE <i>·</i> KEPLER CORRIDOR';const order=['build','space','surface','return'];document.querySelectorAll('.stage').forEach(n=>{n.classList.toggle('active',n.dataset.stage===p);n.classList.toggle('complete',order.indexOf(n.dataset.stage)<order.indexOf(p));});if(configuredPlan){const body=designModifiers.destination.toUpperCase();$('location').textContent=body+' · '+(p==='build'?'CONFIGURED EXPEDITION':p==='surface'?'SURVEY OPERATIONS':'FLIGHT CORRIDOR');}renderObjectives();}
function burst(position,col,count=12,power=4){for(let i=0;i<count;i++){const m=mesh(sharedGeometries.particle,material(col,0,.4,true),effects,position.x,position.y,position.z);particles.push({mesh:m,velocity:new THREE.Vector3((Math.random()-.5)*power,Math.random()*power,(Math.random()-.5)*power),life:.3+Math.random()*.45,max:.75});}}
function pulse(position,col,radius=5){const g=new THREE.Group();g.position.copy(position);g.position.y=.08;effects.add(g);const r=ring(.95,.05,col,g,0);rings.push({group:g,ring:r,age:0,life:.7,radius});}
function removeObject(o){o.removeFromParent();}
const sharedGeometries={bullet:new THREE.SphereGeometry(.09,6,5),particle:new THREE.SphereGeometry(.07,5,4)};
function spawnEnemy(){const p=playerPos();let x,z;if(isFlying()){x=(Math.random()-.5)*26;z=-18-Math.random()*10;}else{let a=Math.random()*Math.PI*2;const d=19+Math.random()*6;x=clamp(p.x+Math.sin(a)*d,-25,25);z=clamp(p.z+Math.cos(a)*d,-23,23);}const m=enemyMesh();m.position.set(x,isFlying()?1.4+Math.random()*1.4:1.7,z);enemies.push({mesh:m,hp:isFlying()?50:42,maxHp:50,fireCD:1+Math.random()*2,phase:Math.random()*6,serial:spawnSerial++});}
function hitEnemy(e,dmg){e.hp-=dmg;burst(e.mesh.position,'#f7bdcd',3,1.8);stats.hits++;$('hitmarker').style.left=pointer.x+'px';$('hitmarker').style.top=pointer.y+'px';$('hitmarker').style.opacity='1';if(e.hp<=0){burst(e.mesh.position,'#fba3be',20,6);pulse(e.mesh.position,'#ed919d',2.7);mission.kills++;mission.score+=100;crew[mission.active].charge=Math.min(100,crew[mission.active].charge+9);tone(100,.2,'sawtooth',.025);removeObject(e.mesh);enemies=enemies.filter(n=>n!==e);}}
function aoe(pos,radius,damage){for(const e of [...enemies])if(e.mesh.position.distanceTo(pos)<radius)hitEnemy(e,damage);pulse(pos,ROLES[mission.active].color,radius);burst(new THREE.Vector3(pos.x,1,pos.z),ROLES[mission.active].color,22,8);screenShake=.18;}
function addBullet(origin,direction,damage,col,hostile=false,speed=30,life=1.1){const o=mesh(sharedGeometries.bullet,material(col,0,.2,true),effects);o.position.copy(origin);o.scale.set(.8,.8,3.2);o.quaternion.setFromUnitVectors(new THREE.Vector3(0,0,1),direction);projectiles.push({mesh:o,velocity:direction.clone().multiplyScalar(speed),life,damage,hostile});}
function aimDirection(){const p=playerPos();raycaster.setFromCamera(mouseNDC,camera);if(raycaster.ray.intersectPlane(aimPlane,aimPoint)){lastAim.copy(aimPoint).sub(new THREE.Vector3(p.x,1,p.z));lastAim.y=0;if(lastAim.lengthSq()>.01)lastAim.normalize();}return lastAim;}
function shoot(){if(mission.paused||mission.ended)return;const c=crew[mission.active],r=ROLES[mission.active];if(!fire(c))return;const dir=aimDirection().clone();const p=playerPos();const origin=new THREE.Vector3(p.x, isFlying()?1.9:1.1,p.z).addScaledVector(dir,isFlying()?2.4:.8);const pellets=r.id===3?6:1;for(let i=0;i<pellets;i++){let a=(Math.random()-.5)*(r.id===3?(pointer.right?.24:.52):(pointer.right?.008:.05));const d=dir.clone().applyAxisAngle(new THREE.Vector3(0,1,0),a);addBullet(origin,d,r.damage*(c.buff>0&&r.id===2?1.6:1),r.color,false,r.id===1?26:38,r.id===3?.55:1.05);}stats.shots++;burst(origin,r.color,3,1.3);tone(r.id===3?95:r.id===1?720:r.id===2?190:340,.06,r.id===1?'sine':'triangle',.02);}
function heal(amount,shipAmount=0){const p=playerPos();for(let i=0;i<crew.length;i++)if(isFlying()||units[i].group.position.distanceTo(p)<9){crew[i].hp=clamp(crew[i].hp+amount,0,100);burst(units[i].group.position,'#9cdeb1',3,2);}if(isFlying()||Math.hypot(p.x-ship.position.x,p.z-ship.position.z)<12)mission.hull=clamp(mission.hull+shipAmount,0,100);pulse(p,'#9cdeb1',6);}
function createDeployable(kind){const p=playerPos(),g=new THREE.Group();g.position.set(p.x,0,p.z);effects.add(g);box(.8,.4,.8,kind==='heal'?'#607e70':'#7a5a6c',g,0,.3,0);const barrel=box(.18,.2,.9,'#c6b6cf',g,0,.7,.2);glow(.5,.06,.5,kind==='heal'?'#9cdeb1':'#ed919d',g,0,.53,0);deployables.push({group:g,barrel,kind,life:16,cd:0});pulse(p,kind==='heal'?'#9cdeb1':'#ed919d',3);}
function dash(power=4.5){const u=units[mission.active];const p=playerPos();let d=movementDirection();if(d.lengthSq()<.1)d=lastAim.clone();p.addScaledVector(d,power);p.x=clamp(p.x,-24,24);p.z=clamp(p.z,isFlying()?-13:-23,isFlying()?14:23);if(!isFlying())resolveCollision(u.group.position);pulse(p,ROLES[mission.active].color,3);burst(new THREE.Vector3(p.x,1,p.z),ROLES[mission.active].color,14,3);}
function useAbility(slot){if(mission.paused||mission.ended)return;const c=crew[mission.active],r=ROLES[mission.active];if(!ability(c,slot)){if(slot==='f')toast('Ultimate charging · '+Math.floor(c.charge)+'%');else toast('Ability cooling down · '+Math.ceil(c[slot==='q'?'qCD':'altCD'])+'s');return;}stats.abilities++;tone(650,.2,'sine',.035);const p=playerPos().clone();if(slot==='q'){if(r.id===0){dash(6);c.buff=2;c.shield=1;toast('AFTERBURNER · Mobility boost');}if(r.id===1){if(isFlying()){heal(18,20);c.shield=2;}else createDeployable('heal');toast('REPAIR SENTRY · Restoration field active');}if(r.id===2){if(isFlying()){c.buff=5;toast('COMBAT PROTOCOL · Fire rate boosted');}else{createDeployable('turret');toast('COMBAT TURRET · Covering your position');}}if(r.id===3){crew.forEach(n=>{n.ammo=ROLES[n.id].mag;n.reloading=0;n.stamina=100;});mission.fuel=Math.min(100,mission.fuel+10);pulse(p,r.color,8);toast('SUPPLY DROP · Crew ammunition and stamina restored');}}
if(slot==='alt'){if(r.id===0){mission.decoy=7;c.shield=1;pulse(p,r.color,7);toast('HOLO DECOY · Enemy targeting disrupted');}if(r.id===1){heal(26,15);toast('REPAIR BURST · Crew +26 · Hull +15 when in range');}if(r.id===2){const target=aimPoint.clone();target.y=1;target.sub(p).clampLength(0,14).add(p);aoe(target,6,70);toast('FRAG GRENADE · Area cleared');}if(r.id===3){aoe(p,8,60);c.shield=1.2;toast('SHOCKWAVE · Nearby hostiles repelled');}}
if(slot==='f'){if(r.id===0){mission.slow=9;c.buff=9;toast('TIME DILATION · Enemies slowed for 9 seconds');}if(r.id===1){crew.forEach(n=>{n.hp=100;n.shield=5;});mission.hull=Math.min(100,mission.hull+50);pulse(p,r.color,24);burst(p,r.color,50,12);toast('NANITE STORM · Crew restored · Hull +50');}if(r.id===2){c.buff=9;c.ammo=r.mag;c.reloading=0;toast('OVERDRIVE · Unlimited ammunition for 9 seconds');}if(r.id===3){const targets=[...enemies].map(e=>e.mesh.position.clone());for(const t of targets)aoe(t,6,120);if(!targets.length)aoe(p,14,120);toast('ORBITAL BARRAGE · Strike confirmed');}}
}
function clearCombat(){for(const e of enemies)removeObject(e.mesh);enemies=[];for(const b of projectiles)removeObject(b.mesh);projectiles=[];for(const d of deployables)removeObject(d.group);deployables=[];spawnClock=1;}
function transition(){if(!nextPhase(mission))return;if(mission.ended){finish(true);return;}clearCombat();pointer.left=false;pointer.right=false;interaction=null;$('interaction').style.display='none';crew.forEach(c=>{c.ammo=ROLES[c.id].mag;c.reloading=0;c.hp=Math.min(100,c.hp+20);c.charge=Math.min(100,c.charge+15);});const fly=isFlying();base.visible=mission.phase==='build'||fly;ground.visible=!fly;captureGroup.visible=mission.phase==='surface';base.children.forEach(o=>{if(o!==ship)o.visible=!fly;});units.forEach((u,i)=>{u.group.visible=!fly;u.selection.visible=!fly&&i===mission.active;u.group.position.set((i-1.5)*1.3,.05,5);});ship.position.set(0,fly?1.1:.6,6);ship.rotation.set(0,0,0);engineFlames.forEach(e=>e.visible=fly);objectiveLabels.forEach(n=>n.style.display='none');scene.fog.density=fly?.0035:.012;scene.background.set(fly?'#100e20':'#20182e');if(mission.phase==='surface'){ship.position.set(0,.6,1);base.visible=true;ship.visible=true;units.forEach(u=>u.group.position.z=7);toast('KEPLER IV · Secure three relic beacons. Hold E inside each ring.');for(let i=0;i<4;i++)spawnEnemy();}else{toast(mission.phase==='space'?'LIFTOFF · Dodge interceptors and survive the transit.':'RETURN VECTOR · Survive until the jump gate opens.');for(let i=0;i<3;i++)spawnEnemy();}updatePhaseUI();tone(800,.45,'sine',.04);}
$('launch').onclick=transition;
function resolveCollision(p){for(const o of [{x:ship.position.x,z:ship.position.z,r:3.2},...(mission.phase==='build'?stations.map(s=>({x:s.group.position.x,z:s.group.position.z,r:1.35})):beacons.map(b=>({x:b.x,z:b.z,r:.8})))]){let dx=p.x-o.x,dz=p.z-o.z,d=Math.hypot(dx,dz),r=o.r+.35;if(d<r){if(d<.001){dx=1;dz=0;d=1;}p.x=o.x+dx/d*r;p.z=o.z+dz/d*r;}}p.x=clamp(p.x,-25,25);p.z=clamp(p.z,-24,24);}
function movementDirection(){let x=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0),z=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0);const norm=normalizeMove(x,z);const forward=new THREE.Vector3().subVectors(camera.position,cameraTarget);forward.y=0;forward.normalize();const right=new THREE.Vector3(forward.z,0,-forward.x);return right.multiplyScalar(norm.x).addScaledVector(forward,norm.z);}
function hurt(amount,shipHit=false){amount*=designModifiers.difficulty==='cadet'?.75:designModifiers.difficulty==='expert'?1.3:1;if(mission.ended||invulnerable>0||mission.phase==='build')return;const c=crew[mission.active];if(c.shield>0||mission.decoy>0)return;if(isFlying()||shipHit)mission.hull-=amount;else c.hp-=amount;screenShake=.13;invulnerable=.18;$('damage').style.opacity='.7';setTimeout(()=>$('damage').style.opacity='0',160);tone(70,.12,'sawtooth',.02);if(mission.hull<=0||c.hp<=0)finish(false);}
function updateInteraction(dt){interaction=null;const p=playerPos();if(mission.phase==='build'){let nearest=null,dist=Infinity;for(const s of stations){const d=p.distanceTo(s.group.position);if(d<dist){dist=d;nearest=s;}}if(dist<3.5&&!nearest.done){interaction={type:'station',target:nearest};const valid=mission.active===nearest.index;$('interact-title').textContent=valid?'INITIALIZE '+ROLES[nearest.index].job.toUpperCase():'SPECIALIST REQUIRED';$('interact-detail').textContent=valid?'Hold E to assemble · '+Math.round(nearest.progress*100)+'%':'Switch to '+ROLES[nearest.index].name+' ['+(nearest.index+1)+']';if(keys.has('e')&&valid){const completed=advanceProgress(mission.buildProgress,nearest.index,dt*(mission.active===1?.65:.5));nearest.progress=mission.buildProgress[nearest.index];if(Math.random()<dt*14)burst(nearest.part.getWorldPosition(tmp),colors[nearest.index],3,2);if(completed){nearest.done=true;mission.installed++;mission.score+=200;crew[mission.active].charge=Math.min(100,crew[mission.active].charge+20);nearest.part.visible=false;pulse(nearest.group.position,colors[nearest.index],4);tone(880,.2);toast(ROLES[nearest.index].job+' online · '+(mission.installed===4?'All systems ready. Launch expedition.':'Switch crew to activate the next system.'));renderObjectives();}}$('interact-progress').style.width=nearest.progress*100+'%';}}
if(mission.phase==='surface'){const b=beacons.find(b=>!b.done&&Math.hypot(p.x-b.x,p.z-b.z)<3.3);if(b){interaction={type:'beacon',target:b};$('interact-title').textContent='EXTRACT RELIC '+ 'ABC'[b.index];$('interact-detail').textContent='Hold E · '+Math.round(b.progress*100)+'% · '+(mission.active===0?'Pilot capture bonus':'Defend the signal');if(keys.has('e')){const completed=advanceProgress(mission.captureProgress,b.index,dt*(mission.active===0?.3:.19)*designModifiers.captureRate);b.progress=mission.captureProgress[b.index];if(completed){b.done=true;mission.captured++;mission.score+=500;b.core.material=material('#d5f591',.2,.5,true);b.ring.material.color.set('#d5f591');crew[mission.active].charge=Math.min(100,crew[mission.active].charge+25);pulse(b.group.position,'#d5f591',7);toast(mission.captured===3?'All relics secured · Return to orbit using the mission panel.':'Relic '+ 'ABC'[b.index]+' secured · '+mission.captured+'/3');tone(900,.3);}if(hudClock<=.05)renderObjectives();}$('interact-progress').style.width=b.progress*100+'%';}}
$('interaction').style.display=interaction?'flex':'none';interacting=!!interaction&&keys.has('e');}
function updateMovement(dt){const c=crew[mission.active],r=ROLES[mission.active],u=units[mission.active],p=playerPos(),dir=movementDirection(),moving=dir.lengthSq()>.1;let sprint=keys.has('shift')&&c.stamina>1&&moving&&!pointer.right&&!interacting;const speed=(isFlying()?9:r.speed)*designModifiers.speed*(pointer.right?.58:1)*(interacting?.4:1)*(sprint?1.65:1)*(c.buff>0&&r.id===0?1.4:1);c.stamina=clamp(c.stamina+dt*(sprint?-22:16*designModifiers.energyRegen),0,100);p.addScaledVector(dir,speed*dt);if(isFlying()){p.x=clamp(p.x,-16,16);p.z=clamp(p.z,-10,15);p.y=1.6+Math.sin(totalTime*1.7)*.12;ship.rotation.z=THREE.MathUtils.damp(ship.rotation.z,-dir.x*.25,8,dt);ship.rotation.x=THREE.MathUtils.damp(ship.rotation.x,dir.z*.13,8,dt);}else{resolveCollision(p);const facing=mouseInside?aimDirection():moving?dir:null;if(facing){const target=Math.atan2(facing.x,facing.z);let diff=Math.atan2(Math.sin(target-u.group.rotation.y),Math.cos(target-u.group.rotation.y));u.group.rotation.y+=diff*Math.min(1,dt*15);}u.walk+=dt*(moving?12:1);u.legs.forEach((l,k)=>l.rotation.x=moving?Math.sin(u.walk+k*Math.PI)*.55:0);u.arms.forEach((a,k)=>a.rotation.x=pointer.left?-.8:moving?Math.sin(u.walk+k*Math.PI)*.3:0);u.group.position.y=.05+(moving?Math.abs(Math.sin(u.walk))*.055:0);
// Inactive specialists follow the selected crew member and defend nearby threats.
units.forEach((ally,i)=>{if(i===mission.active)return;const angle=i*2.4,totalOffset=2.4;const target=p.clone().add(new THREE.Vector3(Math.sin(angle)*totalOffset,0,Math.cos(angle)*totalOffset));const delta=target.sub(ally.group.position);delta.y=0;let walk=delta.length()>1;if(walk){ally.group.position.addScaledVector(delta.normalize(),dt*r.speed*.9);resolveCollision(ally.group.position);ally.group.rotation.y=Math.atan2(delta.x,delta.z);}ally.walk+=dt*10;ally.legs.forEach((l,k)=>l.rotation.x=walk?Math.sin(ally.walk+k*Math.PI)*.45:0);ally.aiCD-=dt;let enemy=enemies.find(e=>e.mesh.position.distanceTo(ally.group.position)<12);if(enemy&&ally.aiCD<=0){ally.aiCD=1.15;const from=ally.group.position.clone();from.y=1.1;const d=enemy.mesh.position.clone().sub(from);d.y=0;d.normalize();addBullet(from,d,7,colors[i],false,28,.7);ally.group.rotation.y=Math.atan2(d.x,d.z);}});}
if(pointer.left)shoot();if(pointer.right&&mission.active===1&&c.stamina>8){c.stamina=Math.max(0,c.stamina-dt*20);for(let i=0;i<crew.length;i++)if(units[i].group.position.distanceTo(p)<7||isFlying())crew[i].hp=Math.min(100,crew[i].hp+dt*8);if(isFlying()||Math.hypot(p.x-ship.position.x,p.z-ship.position.z)<9)mission.hull=Math.min(100,mission.hull+dt*4);if(Math.random()<dt*12)burst(new THREE.Vector3(p.x,1,p.z),'#9cdeb1',2,2);}}
function updateEnemies(dt){const ed=dt*(mission.slow>0?.35:1);const p=playerPos();for(const e of [...enemies]){e.phase+=ed*2;const ep=e.mesh.position;let delta=new THREE.Vector3(p.x-ep.x,0,p.z-ep.z),distance=delta.length();if(distance>7){delta.normalize();ep.addScaledVector(delta,ed*(isFlying()?3.4:2.8));}else{ep.x+=Math.cos(e.phase)*ed*1.5;ep.z+=Math.sin(e.phase)*ed*1.5;}ep.y=(isFlying()?2:1.6)+Math.sin(e.phase)*.23;e.mesh.rotation.y=Math.atan2(p.x-ep.x,p.z-ep.z);e.fireCD-=ed;if(e.fireCD<=0&&distance<26&&mission.decoy<=0){e.fireCD=isFlying()?1.8:2.5;const to=new THREE.Vector3(p.x,isFlying()?1.9:1.1,p.z);const d=to.sub(ep).normalize();addBullet(ep.clone(),d,isFlying()?5:9,'#ff758f',true,isFlying()?14:11,3);}}}
function updateProjectiles(dt){for(let i=projectiles.length-1;i>=0;i--){const b=projectiles[i];b.life-=dt;const prev=b.mesh.position.clone();b.mesh.position.addScaledVector(b.velocity,dt*(b.hostile&&mission.slow>0?.4:1));let hit=false;const segment=new THREE.Line3(prev,b.mesh.position);if(b.hostile){const p=playerPos().clone();p.y=isFlying()?1.9:1.1;segment.closestPointToPoint(p,true,tmp);if(tmp.distanceTo(p)<(isFlying()?1.7:.7)){hurt(b.damage);hit=true;}}else{for(const e of [...enemies]){const ep=e.mesh.position.clone();ep.y=b.mesh.position.y;segment.closestPointToPoint(ep,true,tmp);if(tmp.distanceTo(ep)<.85){hitEnemy(e,b.damage);hit=true;break;}}}if(hit||b.life<=0){removeObject(b.mesh);projectiles.splice(i,1);}}}
function updateFX(dt){for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.life-=dt;p.velocity.y-=dt*4;p.mesh.position.addScaledVector(p.velocity,dt);p.mesh.scale.setScalar(Math.max(0,p.life/p.max));if(p.life<=0){removeObject(p.mesh);particles.splice(i,1);}}for(let i=rings.length-1;i>=0;i--){const r=rings[i];r.age+=dt;r.ring.scale.setScalar(1+r.age/r.life*r.radius);r.ring.material.opacity=(1-r.age/r.life)*.8;if(r.age>=r.life){r.ring.geometry.dispose();r.ring.material.dispose();r.group.removeFromParent();rings.splice(i,1);}}for(let i=deployables.length-1;i>=0;i--){const d=deployables[i];d.life-=dt;d.cd-=dt;if(d.cd<=0){d.cd=d.kind==='heal'?1:.3;if(d.kind==='heal'){const p=playerPos();if(p.distanceTo(d.group.position)<8)heal(5,3);const enemy=enemies.find(e=>e.mesh.position.distanceTo(d.group.position)<9);if(enemy){const from=d.group.position.clone();from.y=1;const dir=enemy.mesh.position.clone().sub(from);dir.y=0;addBullet(from,dir.normalize(),8,'#9cdeb1');}}else{const e=enemies.find(e=>e.mesh.position.distanceTo(d.group.position)<18);if(e){const from=d.group.position.clone();from.y=1;const dir=e.mesh.position.clone().sub(from);dir.y=0;d.group.rotation.y=Math.atan2(dir.x,dir.z);addBullet(from,dir.normalize(),12,'#ed919d');}}}if(d.life<=0){d.group.removeFromParent();deployables.splice(i,1);}}}
function updateCamera(dt){const p=designInspect?ship.position:playerPos();const angle=.66+orbit;const dist=(isFlying()?43:48)*zoom*(pointer.right?.92:1);cameraTarget.lerp(new THREE.Vector3(p.x*.25,0,p.z*.19),1-Math.exp(-dt*2.3));if(mission.phase==='build')cameraTarget.lerp(new THREE.Vector3(-1,0,0),1-Math.exp(-dt*.6));cameraPos.set(cameraTarget.x+Math.sin(angle)*dist*.73,dist*.69,cameraTarget.z+Math.cos(angle)*dist*.73);camera.position.lerp(cameraPos,1-Math.exp(-dt*4));if(screenShake>0){camera.position.x+=(Math.random()-.5)*screenShake;camera.position.z+=(Math.random()-.5)*screenShake;screenShake=Math.max(0,screenShake-dt);}camera.lookAt(cameraTarget);}
const radar=$('radar').getContext('2d');
function updateRadar(){const w=180,h=150;radar.clearRect(0,0,w,h);const cx=w/2,cy=h/2;radar.strokeStyle='#b8a3d420';radar.lineWidth=.7;for(const r of [23,47,69]){radar.beginPath();radar.arc(cx,cy,r,0,Math.PI*2);radar.stroke();}radar.beginPath();radar.moveTo(cx,5);radar.lineTo(cx,h-5);radar.moveTo(15,cy);radar.lineTo(w-15,cy);radar.stroke();radar.save();radar.translate(cx,cy);radar.rotate(totalTime*.5);const gr=radar.createConicGradient?.(0,0,0);if(gr){gr.addColorStop(0,'#b6a3f400');gr.addColorStop(.9,'#b6a3f400');gr.addColorStop(1,'#b6a3f421');radar.fillStyle=gr;radar.beginPath();radar.arc(0,0,69,0,Math.PI*2);radar.fill();}radar.restore();const plot=(x,z,col,r=2)=>{radar.fillStyle=col;radar.beginPath();radar.arc(cx+x*2.2,cy+z*2.2,r,0,6.284);radar.fill();};if(mission.phase==='build')stations.forEach((s,i)=>plot(s.group.position.x,s.group.position.z,s.done?'#d5f591':colors[i],3));if(mission.phase==='surface')beacons.forEach(b=>plot(b.x,b.z,b.done?'#d5f591':'#b6a3f4',3));enemies.forEach(e=>plot(e.mesh.position.x,e.mesh.position.z,'#ed919d',2));if(!isFlying())units.forEach((u,i)=>plot(u.group.position.x,u.group.position.z,i===mission.active?'#d5f591':'#d6cde2',i===mission.active?3:1.5));else plot(ship.position.x,ship.position.z,'#d5f591',3);}
function updateHUD(){const c=crew[mission.active],r=ROLES[mission.active];$('hull-value').textContent=Math.ceil(Math.max(0,mission.hull))+'%';$('hull-bar').style.width=clamp(mission.hull,0,100)+'%';$('hull-bar').style.background=mission.hull<30?'#ed919d':'#d5f591';$('energy-value').textContent=Math.ceil(c.stamina)+'%';$('energy-bar').style.width=c.stamina+'%';$('fuel-value').textContent=Math.ceil(mission.fuel)+'%';$('fuel-bar').style.width=mission.fuel+'%';$('ammo').textContent=c.reloading>0?'··':c.ammo.toString().padStart(2,'0');$('ammo-state').textContent=c.reloading>0?'RELOAD '+c.reloading.toFixed(1)+'s':c.buff>0&&c.id===2?'OVERDRIVE':'ENERGY CELLS';const sec=Math.ceil(Math.max(0,mission.time));$('timer').textContent='T−'+String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0');$('timer').style.color=sec<25?'#ed919d':'';const p=playerPos();$('coordinates').textContent=(p.x<0?'−':'+')+Math.abs(Math.round(p.x)).toString().padStart(2,'0')+' : '+(p.z<0?'−':'+')+Math.abs(Math.round(p.z)).toString().padStart(2,'0');crew.forEach((n,i)=>{$('crew-state-'+i).textContent=(i===mission.active?'IN CONTROL':'READY')+' · '+Math.ceil(n.hp)+'%';$('crew-health-'+i).style.width=clamp(n.hp,0,100)+'%';$('crew-health-'+i).style.background=n.hp<30?'#ed919d':colors[i];});document.querySelectorAll('.ability').forEach(b=>{let action=b.dataset.action,v=0,text='';if(action==='q'){v=c.qCD/r.qCD;text=c.qCD>0?Math.ceil(c.qCD)+'s':r.skill;}if(action==='alt'){v=c.altCD/r.altCD;text=c.altCD>0?Math.ceil(c.altCD)+'s':r.alt;}if(action==='f'){v=1-c.charge/100;text=c.charge>=100?'ULTIMATE READY':Math.floor(c.charge)+'% CHARGED';}if(action==='r'){v=c.reloading/r.reload;text=c.reloading>0?c.reloading.toFixed(1)+'s':'Reload';}if(['q','alt','f','r'].includes(action)){b.querySelector('small').textContent=text;b.querySelector('.cd').style.transform=`scaleY(${v})`;b.classList.toggle('cooling',v>0);}});if($('distance-label'))$('distance-label').textContent=Math.floor(mission.distance*100)+'% of corridor cleared';updateRadar();if(mission.phase==='surface')renderObjectives();}
function updateLabels(){if(mission.phase!=='build')return;stations.forEach((s,i)=>{const v=new THREE.Vector3(s.group.position.x,3.15,s.group.position.z).project(camera);const n=objectiveLabels[i];n.style.display='block';n.style.left=(v.x*.5+.5)*innerWidth+'px';n.style.top=(-v.y*.5+.5)*innerHeight-parseInt(getComputedStyle($('hud')).top)+'px';n.classList.toggle('done',s.done);n.style.opacity=v.z>1?'0':'.95';n.querySelector('small').textContent=s.done?'SYSTEM ONLINE':ROLES[i].name+' STATION';});}
function finish(won){mission.ended=true;mission.won=won;pointer.left=pointer.right=false;keys.clear();$('end').hidden=false;$('end-title').innerHTML=won?'Welcome<br><em>home, crew.</em>':'Signal<br><em>lost.</em>';$('end-description').textContent=won?'All three relics secured. Kestrel and her crew have made it back to orbit. The frontier remembers.':mission.hull<=0?'Kestrel took critical damage. Use the Engineer’s repair abilities and keep moving to evade incoming fire.':mission.fuel<=0?'Propellant was exhausted. Carry more fuel or reduce spacecraft mass in Mission Control.':crew[mission.active].hp<=0?'Your crew was overwhelmed. Deploy turrets, use dodge, and switch to the Engineer for healing.':'The mission window closed. Assemble all four systems or extract the relics before the countdown ends.';if(won)mission.score+=Math.floor(mission.hull)*10+designModifiers.scienceBonus;if(mission.score>best){best=mission.score;try{localStorage.setItem('tminus-best',best);}catch{}}$('end-stats').innerHTML=`<div><b>${mission.score.toLocaleString()}</b><small>MISSION SCORE</small></div><div><b>${mission.kills}</b><small>HOSTILES CLEARED</small></div><div><b>${best.toLocaleString()}</b><small>PERSONAL BEST</small></div>`;tone(won?660:100,.5);}
$('replay').onclick=()=>{clearCombat();mission=makeMission();crew=makeCrew();stats={shots:0,hits:0,abilities:0};totalTime=0;invulnerable=0;orbit=0;zoom=1;keys.clear();stations.forEach((s,i)=>{s.done=false;s.progress=0;s.part.visible=true;s.group.visible=true;objectiveLabels[i].style.display='block';});beacons.forEach(b=>{b.done=false;b.progress=0;b.core.material=material('#b49adc',.2,.5,true);b.ring.material.color.set('#b7a0f3');});base.visible=true;base.children.forEach(o=>o.visible=true);ground.visible=true;captureGroup.visible=false;ship.position.set(0,.6,0);ship.rotation.set(0,0,0);units.forEach((u,i)=>{u.group.visible=true;u.group.position.set(-4+i*1.5,.05,7.8);u.selection.visible=i===0;});engineFlames.forEach(f=>f.visible=false);scene.fog.density=.012;scene.background.set('#20182e');$('end').hidden=true;$('interaction').style.display='none';applyConfiguredStats();renderCrew();updatePhaseUI();toast('New expedition · Move to your station and hold E.');};
function openModal(content){pausedForModal=!mission.paused;mission.paused=true;keys.clear();pointer.left=pointer.right=false;$('modal-content').innerHTML=content;$('modal').hidden=false;document.body.classList.remove('playing');}
function closeModal(){if(pausedForModal)mission.paused=false;$('modal').hidden=true;}
$('close-modal').onclick=closeModal;$('modal').onclick=e=>{if(e.target===$('modal'))closeModal();};
function showHelp(){openModal(`<div class="eyebrow">FIELD MANUAL / CONTROLS</div><h2>Know your crew.</h2><p>Assemble Kestrel at four specialist stations, survive the transit, extract three relics, then make the jump home. Your other crew members follow and provide covering fire. This expedition is single-player with AI crew and enemies.</p><div class="controls-grid">${[['W A S D / Arrows','Move'],['Left mouse','Fire weapon'],['Right mouse (hold)','Aim / Engineer repair beam'],['Middle mouse','Role secondary ability'],['Mouse wheel / 1–4','Switch crew'],['Shift (hold)','Sprint'],['Space','Dodge · 3.5s cooldown'],['E (hold)','Assemble / extract'],['Q','Role ability'],['F','Ultimate · charges over time'],['R','Reload'],['C / Z','Rotate view / camera zoom'],['Esc / P','Pause / resume'],['H','Field manual']].map(([k,t])=>`<div class="control-row"><kbd>${k}</kbd><span>${t}</span></div>`).join('')}</div><div class="role-help">${ROLES.map(r=>`<div style="--role:${r.color}"><b>${r.icon} ${r.name}</b><p>${r.weapon}. <strong>Q:</strong> ${r.skill}. <strong>MMB:</strong> ${r.alt}. <strong>F:</strong> ${r.ultimate}.</p></div>`).join('')}</div><p>Pilot extracts faster. Engineer restores nearby allies and hull with right mouse. Eliminations and completed objectives charge your ultimate. Use the ability buttons if your mouse has no middle button. Desktop keyboard and mouse recommended.</p><p class="ce-model-note">Source code is provided separately with this release.</p>`);}
$('help').onclick=showHelp;$('settings').onclick=()=>{openModal(`<div class="eyebrow">FLIGHT CONFIGURATION</div><h2>Your cockpit.</h2><p>Settings apply immediately. The mission is paused while this panel is open.</p><label class="setting-row">Graphics quality<select id="quality"><option value="auto">Automatic (recommended)</option><option value="high">High · Soft shadows</option><option value="medium" selected>Balanced</option><option value="low">Performance</option></select></label><label class="setting-row">Camera distance<input id="zoom-setting" type="range" min="0.8" max="1.35" step=".05" value="${zoom}"></label><label class="setting-row">Sound effects<input id="audio-setting" type="checkbox" ${muted?'':'checked'}></label><p>Sound uses synthesized effects. Your best expedition score is saved on this device.</p>`);$('quality').value=quality;$('quality').onchange=e=>{quality=e.target.value;applyGraphicsQuality(quality);};$('zoom-setting').oninput=e=>zoom=Number(e.target.value);$('audio-setting').onchange=e=>{muted=!e.target.checked;updateSound();tone();};};let quality='medium';
function updateSound(){$('sound').textContent=muted?'♪':'♫';$('sound').style.color=muted?'#9e90ad':'#d5f591';$('sound').title=muted?'Enable sound':'Mute sound';$('sound').setAttribute('aria-label',muted?'Enable sound':'Mute sound');}$('sound').onclick=()=>{muted=!muted;updateSound();tone(440,.12);};updateSound();
function pauseToggle(){if(!$('modal').hidden){closeModal();return;}if(mission.ended)return;openModal(`<div class="eyebrow">SYSTEM STANDBY</div><h2>Take a breath.</h2><p>Your expedition is paused. Press Escape or P to return to your crew.</p><button class="primary" id="resume">RESUME EXPEDITION <span>↗</span></button>`);$('resume').onclick=closeModal;}
addEventListener('keydown',e=>{if(planning||experience?.isActive)return;const k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright','tab'].includes(k))e.preventDefault();if(['input','select'].includes(document.activeElement.tagName.toLowerCase())&&k!=='escape')return;if(e.repeat)return;if(k==='escape'||k==='p'){pauseToggle();return;}if(k==='h'){if($('modal').hidden)showHelp();else closeModal();return;}if(mission.paused||mission.ended)return;keys.add(k);if('1234'.includes(k))switchCrew(Number(k)-1);if(k==='r'){if(reload(crew[mission.active]))tone(180,.12);}if(k==='q'||k==='f')useAbility(k);if(k===' '){const c=crew[mission.active];if(ability(c,'dodge')){dash(3.8);tone(250,.1);}}if(k==='c'){orbit+=Math.PI/2;toast('Camera heading rotated');}if(k==='z')zoom=zoom>.95?.82:1.1;});addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
canvas.addEventListener('pointermove',e=>{if(planning||experience?.isActive)return;pointer.x=e.clientX;pointer.y=e.clientY;mouseNDC.set(e.clientX/innerWidth*2-1,-e.clientY/innerHeight*2+1);mouseInside=true;const ret=$('aim-reticle');ret.style.left=e.clientX+'px';ret.style.top=e.clientY+'px';ret.classList.add('visible');document.body.classList.add('playing');});canvas.addEventListener('pointerleave',()=>{mouseInside=false;$('aim-reticle').classList.remove('visible');});canvas.addEventListener('pointerdown',e=>{if(experience?.isActive)return;if(mission.paused||mission.ended)return;e.preventDefault();canvas.setPointerCapture(e.pointerId);pointer.x=e.clientX;pointer.y=e.clientY;mouseNDC.set(e.clientX/innerWidth*2-1,-e.clientY/innerHeight*2+1);if(e.button===0)pointer.left=true;if(e.button===2){pointer.right=true;$('aim-reticle').classList.add('aiming');}if(e.button===1)useAbility('alt');});addEventListener('pointerup',e=>{if(e.button===0)pointer.left=false;if(e.button===2){pointer.right=false;$('aim-reticle').classList.remove('aiming');}});canvas.addEventListener('contextmenu',e=>e.preventDefault());canvas.addEventListener('wheel',e=>{if(experience?.isActive)return;e.preventDefault();if(!mission.paused&&!mission.ended)switchCrew((mission.active+(e.deltaY>0?1:3))%4);},{passive:false});
addEventListener('blur',()=>{keys.clear();pointer.left=pointer.right=false;if(!experience?.isActive&&!planning&&!mission.ended&&$('modal').hidden)pauseToggle();});document.addEventListener('visibilitychange',()=>{if(document.hidden){keys.clear();pointer.left=pointer.right=false;if(!experience?.isActive&&!planning&&!mission.ended&&$('modal').hidden)pauseToggle();}});
renderCrew();updatePhaseUI();updateHUD();
// Decorative route dust, reused rather than recreated every frame.
const dustGeo=new THREE.BufferGeometry(),dustPositions=new Float32Array(220*3);for(let i=0;i<220;i++){dustPositions[i*3]=(Math.random()-.5)*90;dustPositions[i*3+1]=(Math.random()-.5)*30;dustPositions[i*3+2]=(Math.random()-.5)*90;}dustGeo.setAttribute('position',new THREE.BufferAttribute(dustPositions,3));const dust=new THREE.Points(dustGeo,new THREE.PointsMaterial({color:'#baa1e3',size:.09,transparent:true,opacity:.6}));scene.add(dust);dust.visible=false;
const perfGovernor=createPerformanceGovernor();
let perfStats={fps:0,resolution:1.5,drawCalls:0,triangles:0,geometries:0,textures:0};
function applyGraphicsQuality(mode){
 if(!perfGovernor.setMode(mode))return false;
 setQuality(mode==='auto'?'medium':mode);
 perfStats.resolution=renderer.getPixelRatio();
 return true;
}
function monitorFrame(rawDt){
 const result=perfGovernor.observe(rawDt*1000,{visible:!document.hidden,active:!window.tminus?.campaign?.isOpen});
 if(result.changed && Math.abs(renderer.getPixelRatio()-Math.min(devicePixelRatio,result.ratio))>.01){
   renderer.setPixelRatio(Math.min(devicePixelRatio,result.ratio));
 }
 perfStats={fps:result.fps,resolution:renderer.getPixelRatio(),drawCalls:renderer.info.render.calls,
  triangles:renderer.info.render.triangles,geometries:renderer.info.memory.geometries,textures:renderer.info.memory.textures};
}
// WebGL context loss can happen on laptops and after display/sleep changes.
// Pausing on loss prevents simulation from advancing while no frame is visible.
let contextLost=false;
canvas.addEventListener('webglcontextlost',event=>{
 event.preventDefault();contextLost=true;
 keys.clear();pointer.left=pointer.right=false;
 experience?.onFocusLost?.();
 if(!experience?.isActive&&!mission.ended)mission.paused=true;
 const dialog=$('webgl-error');if(dialog){dialog.hidden=false;
  const paragraph=dialog.querySelector('p');if(paragraph)paragraph.textContent='The graphics device reset. Your expedition is paused. The game will reload if graphics are restored.';}
});
canvas.addEventListener('webglcontextrestored',()=>location.reload());
const debugPerf=/(?:\?|&)perf(?:=1|&|$)/.test(location.search||'');
const perfOverlay=debugPerf?document.createElement('output'):null;
if(perfOverlay){perfOverlay.className='tminus-perf-hud';perfOverlay.setAttribute('aria-live','off');document.body.append(perfOverlay);}
let perfOverlayTick=0;
function reportPerformance(dt){if(!perfOverlay)return;perfOverlayTick+=dt;
 if(perfOverlayTick<.5)return;perfOverlayTick=0;
 const p=perfStats;perfOverlay.textContent=`${p.fps||'--'} FPS · ${p.drawCalls} calls · ${p.triangles} tri · GPU ${p.geometries} geo / ${p.textures} tex · DPR ${p.resolution.toFixed(2)} · ${perfGovernor.mode.toUpperCase()}`;
}
let prev=performance.now(),fpsFrames=0,fpsTime=0;
function frame(now){requestAnimationFrame(frame);const rawDt=Math.max(0,(now-prev)/1000),dt=Math.min(.04,rawDt);prev=now;if(contextLost||document.hidden||window.tminus?.campaign?.isOpen)return;if(experience?.isActive&&!planning){experience.update(dt);experience.renderWorld?.(scene,camera);experience.renderInset?.();monitorFrame(rawDt);reportPerformance(rawDt);return;}if(!mission.paused&&!mission.ended){totalTime+=dt;mission.elapsed+=dt;mission.time-=dt;mission.slow=Math.max(0,mission.slow-dt);mission.decoy=Math.max(0,mission.decoy-dt);invulnerable=Math.max(0,invulnerable-dt);crew.forEach(c=>tickCrew(c,dt));updateMovement(dt);updateInteraction(dt);if(mission.phase==='build'){stations.forEach((s,i)=>{s.part.rotation.y=totalTime*.6+i;s.part.position.y=1.8+Math.sin(totalTime*1.8+i)*.1;});}else{spawnClock-=dt;const maxEnemies=isFlying()?9:10;if(spawnClock<=0&&enemies.length<maxEnemies){spawnClock=isFlying()?2.6:4;spawnEnemy();}updateEnemies(dt);if(isFlying()){mission.fuel=Math.max(0,mission.fuel-dt*.3/designModifiers.speed);if(mission.fuel<=0)finish(false);mission.distance=clamp(1-mission.time/(mission.phase==='space'?70:42),0,1);engineFlames.forEach(f=>f.scale.y=.8+Math.sin(totalTime*30)*.16);const arr=dustGeo.attributes.position.array;for(let i=0;i<220;i++){arr[i*3+2]+=dt*22;if(arr[i*3+2]>45)arr[i*3+2]=-45;}dustGeo.attributes.position.needsUpdate=true;}beacons.forEach(b=>{b.core.rotation.y+=dt;b.core.position.y=2.45+Math.sin(totalTime*2+b.index)*.12;});}updateProjectiles(dt);updateFX(dt);if(mission.time<=0){if(mission.phase==='space'||mission.phase==='return')transition();else finish(false);}hudClock-=dt;if(hudClock<=0){hudClock=.1;updateHUD();}if(toastClock>0){toastClock-=dt;if(toastClock<=0)$('toast').classList.remove('visible');}const op=Number($('hitmarker').style.opacity||0);if(op>0)$('hitmarker').style.opacity=Math.max(0,op-dt*6).toString();}dust.visible=isFlying();if(!mission.paused||designInspect){if(designInspect)orbit+=dt*.13;updateCamera(dt);}updateLabels();renderer.render(scene,camera);monitorFrame(rawDt);reportPerformance(rawDt);fpsFrames++;fpsTime+=rawDt;if(fpsTime>=2){$('fps').textContent=Math.round(fpsFrames/fpsTime)+' FPS · SYSTEM ONLINE';fpsFrames=0;fpsTime=0;}}
requestAnimationFrame(frame);setTimeout(()=>{$('loading').style.opacity='0';setTimeout(()=>$('loading').remove(),650);toast('Welcome, Pilot. WASD to move · Hold E at Hull Frame · H for controls.');},550);
// A deterministic inspection surface for QA and future mission extensions.
window.tminus={get mission(){return mission;},get crew(){return crew;},get stats(){return stats;},get enemies(){return enemies;},get units(){return units;},get renderer(){return renderer;},get ship(){return ship;},switchCrew,showHelp,setPlanning,previewDesign,inspectDesign,startConfiguredExpedition,clearDesignPreview,setGraphicsQuality:applyGraphicsQuality,get performance(){return {...perfStats,...estimateSceneMemory(scene)}},get performanceMode(){return perfGovernor.mode}};
initPlanner(window.tminus,{autoOpen:false});
experience=createCrewExperience(window.tminus);
applyGraphicsQuality('auto'); // consistent initial shadow and resolution budget
initCampaign(window.tminus);

function applyConfiguredStats(){if(!configuredPlan)return;mission.fuel=designModifiers.fuelReserve;mission.time=designModifiers.difficulty==='cadet'?220:designModifiers.difficulty==='expert'?145:180;}
function setPlanning(value,restorePaused=false){planning=value;experience?.planningChanged(value);mission.paused=value?true:restorePaused;keys.clear();pointer.left=pointer.right=false;$('aim-reticle').classList.remove('visible');if(value){$('modal').hidden=true;document.body.classList.remove('playing');}else{designInspect=false;if(configuredPlan)previewDesign(configuredPlan);else if(designHardware){designHardware.removeFromParent();designHardware=null;}}}
function previewDesign(plan){if(designHardware){designHardware.traverse(o=>{if(o.userData.designOwned&&o.geometry)o.geometry.dispose();});designHardware.removeFromParent();}designHardware=new THREE.Group();ship.add(designHardware);const size=plan.array==='large'?2.7:plan.array==='standard'?1.9:1.2;for(const sign of [-1,1]){box(2,.08,.14,'#81778d',designHardware,sign*4,1.2,.8);const panel=box(size,.07,3,'#273e64',designHardware,sign*(4.6+size*.3),1.22,.8,.65);for(let n=0;n<5;n++)box(size,.018,.025,'#8b8bbc',designHardware,sign*(4.6+size*.3),1.264,-.4+n*.58);for(let n=0;n<3;n++)box(.025,.018,2.9,'#7186b0',designHardware,sign*(4.6+size*.3)-size*.4+n*size*.4,1.264,.8);}
const payloadColors=['#ed919d','#edbd81','#9cdeb1','#b7a0f3','#c5e8e8'];plan.payload.forEach((id,i)=>{const x=i%2?-.8:.8,z=-.7+Math.floor(i/2)*.65;box(.35,.3,.48,'#5e576b',designHardware,x,1.91,z);const pod=glow(.2,.07,.13,payloadColors[i],designHardware,x,2.08,z+.2);pod.userData.designOwned=true;});if(plan.radio==='deep'){const g=mesh(new THREE.SphereGeometry(.75,20,12,0,Math.PI*2,0,Math.PI/2),material('#d3c5de',.6,.4),designHardware,0,2.35,1.8);g.rotation.x=-.6;g.userData.designOwned=true;}else box(.05,.9,.05,'#c9bdd4',designHardware,0,2.4,1.8);}
function inspectDesign(value){designInspect=value;if(value){cameraTarget.set(0,1,0);zoom=.85;}}
function startConfiguredExpedition(plan,modifiers){configuredPlan=JSON.parse(JSON.stringify(plan));designModifiers={...modifiers};$('replay').onclick();previewDesign(plan);toast('Design loaded · Mass changes speed, arrays restore stamina, downlink changes extraction rate.');experience?.configuredLaunch();}

function clearDesignPreview(){if(designHardware){designHardware.removeFromParent();designHardware=null;}}
